import unittest
import stream_ops as api

class IndependentBehavior(unittest.TestCase):
    def test_tail(self): self.assertEqual(api.split_packets([0,1,2,3,4,5,6],3),[[0,1,2],[3,4,5],[6]])
    def test_short(self): self.assertEqual(api.split_packets([7],4),[[7]])
    def test_empty(self): self.assertEqual(api.split_packets([],3),[])
    def test_unit(self): self.assertEqual(api.split_packets([5,6],1),[[5],[6]])
    def test_invalid(self):
        with self.assertRaises(ValueError): api.split_packets([1,2],-1)
    def test_helper(self): self.assertEqual(api.flatten([[1],[],[2,3]]),[1,2,3])
